private static int decodeOctets(int i, ByteBuffer bb, StringBuilder sb) {
    try {
        int b1 = bb.get() & 0xFF;
        if (b1 < 0x80) { // ASCII
            sb.append((char) b1);
            return i + 1;
        }
        if ((b1 >> 5) == 0x06) { // 2-byte sequence
            int b2 = bb.get() & 0x3F;
            int code = ((b1 & 0x1F) << 6) | b2;
            sb.append((char) code);
            return i + 1;
        }
        if ((b1 >> 4) == 0x0E) { // 3-byte sequence
            int b2 = bb.get() & 0x3F;
            int b3 = bb.get() & 0x3F;
            int code = ((b1 & 0x0F) << 12) | (b2 << 6) | b3;
            sb.append((char) code);
            return i + 1;
        }
        if ((b1 >> 3) == 0x1E) { // 4-byte sequence
            int b2 = bb.get() & 0x3F;
            int b3 = bb.get() & 0x3F;
            int b4 = bb.get() & 0x3F;
            int code = ((b1 & 0x07) << 18) | (b2 << 12) | (b3 << 6) | b4;
            if (code <= 0xFFFF) {
                sb.append((char) code);
            } else {
                int cp = code - 0x10000;
                char high = (char) ((cp >> 10) + 0xD800);
                char low = (char) ((cp & 0x3FF) + 0xDC00);
                sb.append(high).append(low);
            }
            return i + 1;
        }
        // If we reach here, the first byte is not a valid UTF-8 start byte.
        sb.append('\uFFFD'); // Unicode replacement character
        return i + 1;
    } catch (BufferUnderflowException e) {
        throw new IllegalArgumentException("Insufficient bytes in buffer for UTF‑8 decoding", e);
    }
}

