public void generateGraph(Graph<V,E> target, Map<String,V> resultMap) {
    if (target == null) throw new IllegalArgumentException("target graph cannot be null");
    if (resultMap == null) throw new IllegalArgumentException("resultMap cannot be null");
    try {
        // Create two partitions with 3 vertices each
        java.util.List<V> partA = new java.util.ArrayList<>();
        java.util.List<V> partB = new java.util.ArrayList<>();
        for (int i = 0; i < 3; i++) {
            V a = (V) ("A" + i);
            target.addVertex(a);
            partA.add(a);
            resultMap.put("A" + i, a);
        }
        for (int i = 0; i < 3; i++) {
            V b = (V) ("B" + i);
            target.addVertex(b);
            partB.add(b);
            resultMap.put("B" + i, b);
        }
        // Add all edges between the two partitions
        for (V from : partA) {
            for (V to : partB) {
                target.addEdge(from, to);
            }
        }
    } catch (Exception e) {
        throw new RuntimeException("Failed to generate complete bipartite graph", e);
    }
}

