public static Class<?>[] resolveArguments(Type genericType, Class<?> targetType) {
    if (!(genericType instanceof ParameterizedType)) {
        return null;
    }
    ParameterizedType pt = (ParameterizedType) genericType;
    Type[] args = pt.getActualTypeArguments();
    Class<?>[] result = new Class<?>[args.length];
    for (int i = 0; i < args.length; i++) {
        Type t = args[i];
        Class<?> cls = null;
        if (t instanceof Class<?>) {
            cls = (Class<?>) t;
        } else if (t instanceof ParameterizedType) {
            cls = (Class<?>) ((ParameterizedType) t).getRawType();
        } else if (t instanceof TypeVariable<?>) {
            TypeVariable<?> tv = (TypeVariable<?>) t;
            Type[] bounds = tv.getBounds();
            if (bounds != null && bounds.length > 0) {
                Type bound = bounds[0];
                if (bound instanceof Class<?>) {
                    cls = (Class<?>) bound;
                } else if (bound instanceof ParameterizedType) {
                    cls = (Class<?>) ((ParameterizedType) bound).getRawType();
                }
            }
        }
        if (cls == null) {
            return null;
        }
        result[i] = cls;
    }
    return result;
}

@Override public void accept(final METRICS data){
    if (data == null) {
        throw new IllegalArgumentException("data cannot be null");
    }
    try {
        METRICS existing = cache.get(data);
        if (existing != null) {
            // Attempt to merge using a known merge method if it exists
            try {
                java.lang.reflect.Method mergeMethod = data.getClass().getMethod("merge", data.getClass());
                mergeMethod.invoke(existing, data);
            } catch (NoSuchMethodException nsme) {
                // No merge support; replace the existing entry
                cache.put(data, data);
            } catch (Exception e) {
                // Any other reflection or runtime exception
                throw new RuntimeException("Error merging metric", e);
            }
        } else {
            cache.put(data, data);
        }
    } catch (Exception e) {
        throw new RuntimeException("Failed to accept metric into cache", e);
    }
}

void insertBefore(Bucket bucket){
    if (bucket == null) {
        throw new IllegalArgumentException("bucket cannot be null");
    }
    if (this == bucket) {
        throw new IllegalArgumentException("Cannot insert before itself");
    }
    // If this is already directly before bucket, nothing to do
    if (bucket.prev == this) {
        return;
    }
    // Detach this from its current place
    if (this.prev != null) {
        this.prev.next = this.next;
    }
    if (this.next != null) {
        this.next.prev = this.prev;
    }
    // Insert this before bucket
    this.next = bucket;
    this.prev = bucket.prev;
    if (bucket.prev != null) {
        bucket.prev.next = this;
    }
    bucket.prev = this;
}

