public Mappings diffStructure(String tableName, Mappings mappings) {
    // Guard against null inputs
    if (tableName == null || mappings == null) {
        return new Mappings();
    }
    try {
        // Retrieve the historical mapping for the given table name.
        // Assumes there is a map of tableName -> Mappings named historyMappingMap.
        Mappings historical = historyMappingMap == null ? null : historyMappingMap.get(tableName);
        if (historical == null) {
            return new Mappings();
        }

        // Assume Mappings exposes a Map<String,Object> of its properties via getProperties().
        Map<String, Object> currentProps = mappings.getProperties();
        Map<String, Object> oldProps = historical.getProperties();

        if (currentProps == null) {
            currentProps = new HashMap<>();
        }
        if (oldProps == null) {
            oldProps = new HashMap<>();
        }

        Mappings diff = new Mappings();
        // Iterate through all fields present in the historical mapping
        for (String fieldName : oldProps.keySet()) {
            // Skip the special _source configuration
            if ("_source".equals(fieldName)) {
                continue;
            }
            // If the current mapping does not contain this field, add it to the diff
            if (!currentProps.containsKey(fieldName)) {
                diff.put(fieldName, oldProps.get(fieldName));
            }
        }
        return diff;
    } catch (Exception e) {
        // In case of unexpected errors, return an empty mapping.
        return new Mappings();
    }
}

