static long compressTimeBucket(long timeBucket, int dayStep) {
    if (dayStep <= 0) {
        throw new IllegalArgumentException("dayStep must be positive");
    }
    long year = timeBucket / 10000;
    long month = (timeBucket / 100) % 100;
    long day = timeBucket % 100;
    long newDay = ((day - 1) / dayStep) * dayStep + 1;
    return year * 10000 + month * 100 + newDay;
}

public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    // Basic validation
    if (str == null) {
        return 0;
    }
    if (len <= 0) {
        return 0;
    }
    final int strLen = str.length();
    if (index < 0 || index > strLen || index + len > strLen) {
        throw new IllegalArgumentException("index and length must refer to a valid subsequence");
    }

    int size = 0;
    int i = index;
    final int end = index + len;

    while (i < end) {
        int cp;
        char ch = str.charAt(i);

        if (Character.isHighSurrogate(ch) && (i + 1 < end) && Character.isLowSurrogate(str.charAt(i + 1))) {
            cp = Character.toCodePoint(ch, str.charAt(i + 1));
            i += 2; // two chars consumed
        } else {
            cp = ch;
            i++;
        }

        // Determine UTF-8 byte length for this code point
        if (cp <= 0x7F) {
            size += 1;
        } else if (cp <= 0x7FF) {
            size += 2;
        } else if (cp <= 0xFFFF) {
            size += 3;
        } else {
            size += 4; // supplementary code points (rare but handled)
        }
    }

    return size;
}

