public static AtmosphereRequest wrap(HttpServletRequest request){ 
    if(request==null){ 
        throw new IllegalArgumentException("request cannot be null"); 
    } 
    try{ 
        // If the request is already an AtmosphereRequest simply return it
        if(request instanceof AtmosphereRequest){ 
            return (AtmosphereRequest) request; 
        } 
        // Attempt to construct a wrapper. This assumes AtmosphereRequest has a
        // constructor that accepts HttpServletRequest or a static factory method.
        return new AtmosphereRequest(request); 
    }catch(ClassCastException e){ 
        // In case the request is not an AtmosphereRequest but implements a similar interface
        throw new RuntimeException("Failed to wrap request as AtmosphereRequest", e); 
    }catch(Exception e){ 
        throw new RuntimeException("Unexpected error while wrapping request", e); 
    } 
}

