        prevTreeEdge2.nextTreeEdge2 = nextTreeEdge2;
    }
    if (nextTreeEdge2 != null) {
        nextTreeEdge2.prevTreeEdge2 = prevTreeEdge2;
    }

    // clear this edge's own references
    prevTreeEdge = nextTreeEdge = prevTreeEdge2 = nextTreeEdge2 = null;
}

public static String findAndSubst(String key, Properties props) {
    if (props == null || key == null) {
        return null;
    }
    String value = props.getProperty(key);
    if (value == null) {
        return null;
    }
    try {
        java.util.regex.Pattern regex = java.util.regex.Pattern.compile("\\$\\{([^}]+)\\}");
        java.util.regex.Matcher matcher = regex.matcher(value);
        StringBuffer result = new StringBuffer();
        while (matcher.find()) {
            String varName = matcher.group(1);
            String replacement = props.getProperty(varName);
            if (replacement == null) {
                replacement = "";
            }
            replacement = java.util.regex.Matcher.quoteReplacement(replacement);
            matcher.appendReplacement(result, replacement);
        }
        matcher.appendTail(result);
        return result.toString();
    } catch (Exception e) {
        // In case of any unexpected error return the original value
        return value;
    }
}

