private void pop(final String descriptor) {
    if (descriptor == null || descriptor.isEmpty()) {
        return;
    }
    final char[] chars = descriptor.toCharArray();
    int len = chars.length;
    int i = 0;
    int slotsToPop = 0;

    // Helper to determine slot count for a type starting at position i
    java.util.function.Supplier<Void> parseType = new java.util.function.Supplier<>() {
        @Override
        public Void get() {
            if (i >= len) {
                throw new IllegalArgumentException("Unexpected end of descriptor");
            }
            // Handle array types
            if (chars[i] == '[') {
                // consume all array brackets
                while (i < len && chars[i] == '[') {
                    i++;
                }
                // component type
                if (i >= len) {
                    throw new IllegalArgumentException("Invalid array component in descriptor");
                }
                if (chars[i] == 'L') {
                    // object type
                    while (i < len && chars[i] != ';') {
                        i++;
                    }
                    if (i >= len) {
                        throw new IllegalArgumentException("Unterminated object type in descriptor");
                    }
                    i++; // consume ';'
                    slotsToPop += 1;
                } else {
                    // primitive type
                    char t = chars[i];
                    if (t == 'J' || t == 'D') {
                        slotsToPop += 2;
                    } else if ("BCFISZ".indexOf(t) >= 0) {
                        slotsToPop += 1;
                    } else {
                        throw new IllegalArgumentException("Invalid primitive type in descriptor: " + t);
                    }
                    i++; // consume primitive
                }
                return null;
            }
            // Non-array types
            if (chars[i] == 'L') {
                // object type
                while (i < len && chars[i] != ';') {
                    i++;
                }
                if (i >= len) {
                    throw new IllegalArgumentException("Unterminated object type in descriptor");
                }
                i++; // consume ';'
                slotsToPop += 1;
            } else {
                // primitive type
                char t = chars[i];
                if (t == 'J' || t == 'D') {
                    slotsToPop += 2;
                } else if ("BCFISZ".indexOf(t) >= 0) {
                    slotsToPop += 1;
                } else {
                    throw new IllegalArgumentException("Invalid primitive type in descriptor: " + t);
                }
                i++; // consume primitive
            }
            return null;
        }
    };

    // If method descriptor
    if (chars[0] == '(') {
        i = 1;
        while (i < len && chars[i] != ')') {
            parseType.get();
        }
        if (i >= len || chars[i] != ')') {
            throw new IllegalArgumentException("Malformed method descriptor: " + descriptor);
        }
        i++; // skip ')'
        // Remaining descriptor is return type; we ignore it
    } else {
        // Single-type descriptor
        parseType.get();
    }

    // Pop the determined number of slots from the stack
    if (slotsToPop > 0) {
        pos -= slotsToPop;
        if (pos < 0) {
            pos = 0;
        }
    }
}

@Override public void write(final byte b[],final int off,final int len) throws IOException {
    if (b == null) {
        throw new NullPointerException();
    }
    if (off < 0 || len < 0 || off + len > b.length) {
        throw new IndexOutOfBoundsException("off: " + off + ", len: " + len + ", b.length: " + b.length);
    }
    if (len == 0) {
        return;
    }
    int newCount = count + len;
    if (newCount > buf.length) {
        grow(newCount);
    }
    System.arraycopy(b, off, buf, count, len);
    count = newCount;
}

public static final <V> void swap(V[] arr, int i, int j) {
    if (arr == null) throw new NullPointerException("Array cannot be null");
    int len = arr.length;
    if (i < 0 || i >= len || j < 0 || j >= len) {
        throw new IndexOutOfBoundsException("Index out of bounds: i=" + i + ", j=" + j + ", length=" + len);
    }
    if (i == j) {
        return;
    }
    V temp = arr[i];
    arr[i] = arr[j];
    arr[j] = temp;
}

