public static Pair<Box2D,Box2D> splitAlongXAxis(Box2D box) {
    if (box == null) {
        throw new IllegalArgumentException("box cannot be null");
    }
    double minX = box.getMinX();
    double minY = box.getMinY();
    double width = box.getWidth();
    double height = box.getHeight();
    if (width <= 0 || height <= 0) {
        throw new IllegalArgumentException("Box dimensions must be positive");
    }
    double halfWidth = width / 2.0;
    Box2D left = new Box2D(minX, minY, halfWidth, height);
    Box2D right = new Box2D(minX + halfWidth, minY, halfWidth, height);
    return new Pair<>(left, right);
}

private void enlarge(final int size){
    if (size <= 0) {
        return;
    }
    int currentCapacity = data.length;
    int newCapacity = currentCapacity * 2;
    int requiredCapacity = length + size;
    if (newCapacity < requiredCapacity) {
        newCapacity = requiredCapacity;
    }
    if (newCapacity == currentCapacity) {
        // In case current capacity is zero or doubling didn't increase size
        newCapacity = Math.max(requiredCapacity, currentCapacity + 1);
    }
    byte[] newData = new byte[newCapacity];
    System.arraycopy(data, 0, newData, 0, length);
    data = newData;
}

