public static int writeTo(final DataOutput out, LinkedBuffer node) throws IOException {
    if (node == null) {
        return 0;
    }
    int totalSize = 0;
    LinkedBuffer current = node;
    while (current != null) {
        byte[] buffer = null;
        int length = 0;
        try {
            // Try to read buffer and length using known API
            buffer = current.buffer();  // assume method returning byte[]
            length = current.size();    // assume method returning used length
        } catch (NoSuchMethodError | NullPointerException e) {
            // Fallback: try to access fields directly
            try {
                java.lang.reflect.Field bufField = current.getClass().getField("buffer");
                buffer = (byte[]) bufField.get(current);
            } catch (Exception ignored) { }
            try {
                java.lang.reflect.Field sizeField = current.getClass().getField("size");
                length = sizeField.getInt(current);
            } catch (Exception ignored) { }
            if (buffer == null || length == 0) {
                // Try next pointer
                try {
                    java.lang.reflect.Field nextField = current.getClass().getField("next");
                    current = (LinkedBuffer) nextField.get(current);
                    continue;
                } catch (Exception ignored2) {
                    break;
                }
            }
        }
        if (buffer != null && length > 0) {
            out.write(buffer, 0, length);
            totalSize += length;
        }
        // Move to next buffer node
        try {
            current = current.next(); // assume method returning next node
        } catch (NoSuchMethodError e) {
            try {
                java.lang.reflect.Field nextField = current.getClass().getField("next");
                current = (LinkedBuffer) nextField.get(current);
            } catch (Exception ignored) {
                break;
            }
        }
    }
    return totalSize;
}

