public void readFrom(final InputStream in) throws IOException {
    if (in == null) {
        throw new NullPointerException("Input stream cannot be null");
    }
    // Read all bytes from the InputStream into a byte array
    try (ByteArrayOutputStream bos = new ByteArrayOutputStream()) {
        byte[] buffer = new byte[8192];
        int bytesRead;
        while ((bytesRead = in.read(buffer)) != -1) {
            bos.write(buffer, 0, bytesRead);
        }
        byte[] data = bos.toByteArray();

        // Clear existing buffer and load new data
        // Assume the class has a ByteBuffer field named `buffer`
        if (buffer == null || buffer.capacity() != data.length) {
            this.buffer = ByteBuffer.allocate(data.length);
        } else {
            this.buffer.clear();
        }
        this.buffer.put(data);
        this.buffer.flip(); // reset read pointer to start
    }
}

