@Override protected Object convertToType(final Class<?> type, final Object value) throws Exception {
    if (value == null) {
        return null;
    }
    if (type == null) {
        throw new IllegalArgumentException("Target type cannot be null");
    }
    if (Character.class.equals(type) || type == char.class) {
        if (value instanceof Character) {
            return value;
        }
        if (value instanceof CharSequence) {
            CharSequence cs = (CharSequence) value;
            if (cs.length() == 0) {
                throw new Exception("Cannot convert empty CharSequence to Character");
            }
            return Character.valueOf(cs.charAt(0));
        }
        if (value instanceof String) {
            String s = (String) value;
            if (s.isEmpty()) {
                throw new Exception("Cannot convert empty String to Character");
            }
            return Character.valueOf(s.charAt(0));
        }
        if (value instanceof Number) {
            int num = ((Number) value).intValue();
            return Character.valueOf((char) num);
        }
        if (value instanceof char[]) {
            char[] arr = (char[]) value;
            if (arr.length == 0) {
                throw new Exception("Cannot convert empty char array to Character");
            }
            return Character.valueOf(arr[0]);
        }
        if (value instanceof byte[]) {
            byte[] arr = (byte[]) value;
            if (arr.length == 0) {
                throw new Exception("Cannot convert empty byte array to Character");
            }
            return Character.valueOf((char) arr[0]);
        }
    }
    throw new Exception("Conversion to " + type.getSimpleName() + " is unsupported for value of type " + value.getClass().getSimpleName());
}

