public static int nextPrime(int desiredCapacity){
    if (desiredCapacity <= 2) {
        return 2;
    }
    int candidate = desiredCapacity;
    // Make sure the candidate is odd (except 2 which is handled above)
    if ((candidate & 1) == 0) {
        candidate++;
    }
    while (true) {
        boolean isPrime = true;
        int limit = (int)Math.sqrt(candidate);
        for (int i = 3; i <= limit; i += 2) {
            if (candidate % i == 0) {
                isPrime = false;
                break;
            }
        }
        if (isPrime) {
            return candidate;
        }
        candidate += 2; // Skip even numbers
        // Avoid infinite loop on integer overflow
        if (candidate < 0) {
            throw new ArithmeticException("Prime search overflow for desiredCapacity=" + desiredCapacity);
        }
    }
}

