public short readShort(final int offset){
    // Validate state and inputs
    if (this.bytes == null) {
        throw new IllegalStateException("ClassReader data is null");
    }
    if (offset < 0 || offset > this.bytes.length - 2) {
        throw new IllegalArgumentException("Offset out of bounds: " + offset);
    }
    final byte[] b = this.bytes;
    return (short)(((b[offset] & 0xFF) << 8) | (b[offset + 1] & 0xFF));
}

private static Object copyArrayGrow1(final Object array, final Class<?> newArrayComponentType) {
    if (array == null) {
        if (newArrayComponentType == null) {
            throw new IllegalArgumentException("newArrayComponentType must not be null when array is null");
        }
        return java.lang.reflect.Array.newInstance(newArrayComponentType, 1);
    }

    final Class<?> componentType = array.getClass().getComponentType();
    if (componentType == null) {
        throw new IllegalArgumentException("Provided object is not an array");
    }

    final int oldLength = java.lang.reflect.Array.getLength(array);
    final Object newArray = java.lang.reflect.Array.newInstance(componentType, oldLength + 1);
    System.arraycopy(array, 0, newArray, 0, oldLength);
    return newArray;
}

private int computeBinaryLog(int n){
    if (n <= 0) {
