private JsonObject convertProperties(List<KeyStringValuePair> properties) {
    if (properties == null || properties.isEmpty()) {
        return Json.createObjectBuilder().build();
    }
    JsonObjectBuilder builder = Json.createObjectBuilder();
    for (KeyStringValuePair pair : properties) {
        if (pair == null) {
            continue;
        }
        try {
            String key = pair.getKey();
            if (key == null) {
                continue;
            }
            String value = pair.getValue();
            if (value == null) {
                builder.addNull(key);
            } else {
                builder.add(key, value);
            }
        } catch (Exception e) {
            // Skip any problematic pair but continue processing others
        }
    }
    return builder.build();
}

protected int removeUnusedNodes() {
    if (root == null) {
        return 0;
    }
    int removed = 0;
    java.util.Deque<CategoryNode> nodeStack = new java.util.ArrayDeque<>();
    java.util.Deque<CategoryNode> parentStack = new java.util.ArrayDeque<>();
    nodeStack.push(root);
    parentStack.push(null);
    try {
        while (!nodeStack.isEmpty()) {
            CategoryNode node = nodeStack.pop();
            CategoryNode parent = parentStack.pop();
            java.util.List<CategoryNode> children = node.getChildren();
            if (children != null) {
                for (CategoryNode child : children) {
                    nodeStack.push(child);
                    parentStack.push(node);
                }
            }
            if (!node.isActive()) {
                if (parent != null) {
                    parent.removeChild(node);
                } else {
                    root = null;
                }
                removed++;
            }
        }
    } catch (Exception e) {
        // Handle or log the exception as needed
    }
    return removed;
}

