final String readUtf(final int constantPoolEntryIndex, final char[] charBuffer){
    if (constantPoolEntryIndex <= 0 || constantPoolEntryIndex >= constantPoolOffsets.length) {
        throw new IllegalArgumentException("Constant pool entry index out of bounds: " + constantPoolEntryIndex);
    }
    int offset = constantPoolOffsets[constantPoolEntryIndex];
    // Verify that the entry is a CONSTANT_Utf8
    if (classFileBuffer[offset] != 1) {
        throw new IllegalArgumentException("Constant pool entry at index " + constantPoolEntryIndex + " is not a CONSTANT_Utf8");
    }
    // Read the length field (u2)
    int length = ((classFileBuffer[offset + 1] & 0xFF) << 8) | (classFileBuffer[offset + 2] & 0xFF);
    if (length == 0) {
        return "";
    }
    if (charBuffer.length < length) {
        throw new IllegalArgumentException("Provided char buffer is too small for UTF-8 string of length " + length);
    }
    // Extract the raw bytes for the string
    byte[] utf8Bytes = new byte[length];
    System.arraycopy(classFileBuffer, offset + 3, utf8Bytes, 0, length);
    // Decode the UTF-8 bytes into a String
    String result;
    try {
        result = new String(utf8Bytes, "UTF-8");
    } catch (java.io.UnsupportedEncodingException e) {
        throw new RuntimeException("UTF-8 encoding not supported", e);
    }
    // Copy the characters into the supplied char buffer for potential reuse
    result.getChars(0, length, charBuffer, 0);
    return result;
}

