private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    if (predicate == null) {
        throw new IllegalArgumentException("predicate must not be null");
    }
    if (start == null || stop == null) {
        throw new IllegalArgumentException("start and stop nodes must not be null");
    }
    // Begin traversal at the start node
    OuterFaceCirculator circ = new OuterFaceCirculator(start, dir);
    Node current = start;
    // Use a loop to walk the boundary until a node satisfies the predicate or the stop node is reached
    do {
        if (predicate.test(current)) {
            return circ;
        }
        if (current.equals(stop)) {
            // The stop node itself satisfies the termination condition
            return new OuterFaceCirculator(stop, dir);
        }
        // Advance to the next node in the specified direction
        current = circ.next(); // assumes next() returns the next Node
    } while (current != null && !current.equals(start));
    // If the loop completes without returning, return a circulator positioned at the stop node
    return new OuterFaceCirculator(stop, dir);
}

