        if(byteOffset < 0 || byteOffset + byteLength > byteArrayValue.length){
            throw new IllegalArgumentException("byteOffset+byteLength out of bounds");
        }
    }
    int loc0 = this.length;
    if(loc0 + byteLength > data.length){
        enlarge(byteLength);
    }
    if(byteArrayValue == null){
        for(int i = 0; i < byteLength; i++){
            data[loc0++] = 0;
        }
    }else{
