public int appendLoopOnAppenders(LoggingEvent event){
    if (event == null || appenderList == null){
        return 0;
    }
    int loopCount = 0;
    for (int i = 0; i < appenderList.size(); i++){
        Object obj = appenderList.elementAt(i);
        if (obj instanceof Appender){
            Appender appender = (Appender)obj;
            if (appender != null){
                try{
                    appender.doAppend(event);
                }catch(Throwable t){
                    // ignore and continue with next appender
                }
                loopCount++;
            }
        }
    }
    return loopCount;
}

