protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph){
    if (tour == null || tour.isEmpty()) return null;
    // Map each vertex to its incident edges in the tour
    Map<V, List<E>> adjacency = new HashMap<>();
    for (E e : tour){
        V s = graph.getEdgeSource(e);
        V t = graph.getEdgeTarget(e);
        adjacency.computeIfAbsent(s, k -> new ArrayList<>()).add(e);
        adjacency.computeIfAbsent(t, k -> new ArrayList<>()).add(e);
    }
    // Find a start vertex (an endpoint of a path, i.e., degree 1). If none, pick arbitrary vertex (cycle)
    V start = null;
    for (Map.Entry<V,List<E>> entry : adjacency.entrySet()){
        if (entry.getValue().size() == 1){
            start = entry.getKey();
            break;
        }
    }
    if (start == null){ // cycle: pick any vertex from any edge
        E any = tour.iterator().next();
        start = graph.getEdgeSource(any);
    }
    // Build the ordered lists of vertices and edges
    List<V> vertexList = new ArrayList<>();
    List<E> edgeList   = new ArrayList<>();
    Set<E> usedEdges   = new HashSet<>();
    V current = start;
    while (true){
        vertexList.add(current);
        List<E> edges = adjacency.getOrDefault(current, Collections.emptyList());
        E nextEdge = null;
        for (E e : edges){
            if (!usedEdges.contains(e)){
                nextEdge = e;
                break;
            }
        }
        if (nextEdge == null) break;            // no unused edge from current vertex
        edgeList.add(nextEdge);
        usedEdges.add(nextEdge);
        V s = graph.getEdgeSource(nextEdge);
        V t = graph.getEdgeTarget(nextEdge);
        current = current.equals(s) ? t : s;    // move to the other vertex
    }
    final V src = vertexList.get(0);
    final V dst = vertexList.get(vertexList.size() - 1);
    final Collection<V> vCol = Collections.unmodifiableCollection(new ArrayList<>(vertexList));
    final Collection<E> eCol = Collections.unmodifiableCollection(new ArrayList<>(edgeList));
    // Construct a simple GraphPath instance using an anonymous class
    return new GraphPath<V,E>() {
        public V getStartVertex() { return src; }
        public V getEndVertex()   { return dst; }
        public Collection<V> getVertices() { return vCol; }
        public Collection<E> getEdges()    { return eCol; }
        public double getWeight() { return 0.0; } // weight can be computed if needed
    };
}

