int addConstantNameAndType(final String name, final String descriptor) {
    if (name == null || descriptor == null) {
        throw new IllegalArgumentException("name and descriptor must not be null");
    }

    int nameIdx = findUtf8(name);
    if (nameIdx == NOT_FOUND) {
        nameIdx = addUtf8(name);
    }

    int descIdx = findUtf8(descriptor);
    if (descIdx == NOT_FOUND) {
        descIdx = addUtf8(descriptor);
    }

    for (int i = 1; i < maxPoolSize; i++) {
        if (types[i] == NAME_TYPE && nameIndex[i] == nameIdx && descriptorIndex[i] == descIdx) {
            return i;
        }
    }

    int idx = maxPoolSize;
    if (idx >= types.length) {
        int newCap = Math.max(types.length * 2, idx + 1);
        types = java.util.Arrays.copyOf(types, newCap);
        nameIndex = java.util.Arrays.copyOf(nameIndex, newCap);
        descriptorIndex = java.util.Arrays.copyOf(descriptorIndex, newCap);
    }

    types[idx] = NAME_TYPE;
    nameIndex[idx] = nameIdx;
    descriptorIndex[idx] = descIdx;
    maxPoolSize++;

    return idx;
}

private String unescapeId(String input) {
    if (input == null) {
        return "";
    }
    // Remove surrounding quotes if present
    if (input.length() >= 2 && input.startsWith("\"") && input.endsWith("\"")) {
        input = input.substring(1, input.length() - 1);
    }
    StringBuilder result = new StringBuilder();
    int len = input.length();
    for (int i = 0; i < len; i++) {
        char c = input.charAt(i);
        if (c == '\\') {
            if (i + 1 >= len) {
                // Trailing backslash, treat literally
                result.append('\\');
                break;
            }
            char next = input.charAt(i + 1);
            i++; // skip escape char
            switch (next) {
                case 'n':
                    result.append('\n');
                    break;
                case 't':
                    result.append('\t');
                    break;
                case 'r':
                    result.append('\r');
                    break;
                case 'b':
                    result.append('\b');
                    break;
                case 'f':
                    result.append('\f');
                    break;
                case 'a':
                    result.append('\u0007'); // bell
                    break;
                case 'e':
                    result.append('\u001b'); // escape
                    break;
                case '\\':
                    result.append('\\');
                    break;
                case '"':
                    result.append('\"');
                    break;
                case '\'':
                    result.append('\'');
                    break;
                case 'x':
                    // Hex escape \xNN (exactly two hex digits)
                    int hexlen = 0;
                    int hexVal = 0;
                    while (hexlen < 2 && i + 1 < len) {
                        char hexChar = input.charAt(i + 1);
                        int digit = -1;
                        if (hexChar >= '0' && hexChar <= '9') {
                            digit = hexChar - '0';
                        } else if (hexChar >= 'a' && hexChar <= 'f') {
                            digit = 10 + (hexChar - 'a');
                        } else if (hexChar >= 'A' && hexChar <= 'F') {
                            digit = 10 + (hexChar - 'A');
                        }
                        if (digit < 0) {
                            break;
                        }
                        hexVal = (hexVal << 4) | digit;
                        i++;
                        hexlen++;
                    }
                    if (hexlen > 0) {
                        result.append((char) hexVal);
                    } else {
                        // Invalid hex, keep literal
                        result.append('\\').append('x');
                    }
                    break;
                default:
                    // Octal escape \NNN (up to 3 octal digits)
                    if (Character.isDigit(next) && next >= '0' && next <= '7') {
                        int octVal = next - '0';
                        int digitsSeen = 1;
                        while (digitsSeen < 3 && i + 1 < len) {
                            char octChar = input.charAt(i + 1);
                            if (octChar >= '0' && octChar <= '7') {
                                octVal = (octVal << 3) | (octChar - '0');
                                i++;
                                digitsSeen++;
                            } else {
                                break;
                            }
                        }
                        result.append((char) octVal);
                    } else {
                        // Unknown escape, keep literal
                        result.append(next);
                    }
                    break;
            }
        } else {
            result.append(c);
        }
    }
    return result.toString();
}

