private boolean unlink(ListNodeImpl<E> node) {
    if (node == null) {
        return false;
    }
    ListNodeImpl<E> prev = node.prev;
    ListNodeImpl<E> next = node.next;

    if (prev == null) { // node is the first node
        first = next;
    } else {
        prev.next = next;
    }

    if (next == null) { // node is the last node
        last = prev;
    } else {
        next.prev = prev;
    }

    // Help GC
    node.prev = null;
    node.next = null;

    size--;
    return true;
}

