private Pair<List<Integer>,Long> computeSuffixSum(List<Integer> bounds){
    if(bounds == null){
        throw new IllegalArgumentException("bounds list cannot be null");
    }
    int n = bounds.size();
    // Prepare the suffix list with the same size
    List<Integer> suffix = new ArrayList<>(n);
    for(int i = 0; i < n; i++){
        suffix.add(0); // placeholder
    }
    long runningSum = 0L;
    for(int i = n - 1; i >= 0; i--){
        Integer val = bounds.get(i);
        long cur = (val == null) ? 0L : val.longValue();
        runningSum += cur;
        // Store as Integer (may overflow if sum > Integer.MAX_VALUE, but matches signature)
        suffix.set(i, (int)runningSum);
    }
    return new Pair<>(suffix, runningSum);
}

