        arr[from] = arr[to];
        arr[to] = temp;
        from++;
        to--;
    }
}

private void moveAllListNodes(DoublyLinkedList<E> list) {
    // Guard against null or empty source list
    if (list == null || list.size == 0) {
        return;
    }

    // If the current list is empty, simply adopt the source list's nodes
    if (this.size == 0) {
        this.first = list.first;
        this.last  = list.last;
        this.size  = list.size;
    } else {
        // Link the two lists together
        this.last.next = list.first;
        list.first.prev = this.last;
        this.last = list.last;
        this.size += list.size;
    }

    // Leave the source list empty without moving any of its nodes
    list.first = null;
    list.last  = null;
    list.size  = 0;
}

