}

private List<Integer> computeLowerBounds(List<Integer> keys){
    if (keys == null) throw new IllegalArgumentException("keys cannot be null");
    List<Integer> result = new ArrayList<>(keys.size());
    if (keys.isEmpty()) return result;
    Map<Integer, Integer> lowerBoundMap = new HashMap<>();
    TreeSet<Integer> sorted = new TreeSet<>(keys);
    Integer prev = null;
    for (Integer key : sorted) {
        if (prev == null) {
            lowerBoundMap.put(key, null);
        } else {
            lowerBoundMap.put(key, prev);
        }
        prev = key;
    }
    for (Integer k : keys) {
        result.add(lowerBoundMap.get(k));
    }
    return result;
}

private void pop(final String descriptor) {
    int slots = 0;
    int i = 0;
    // If descriptor represents a method, skip the argument types until ')'
    if (!descriptor.isEmpty() && descriptor.charAt(0) == '(') {
        i++; // skip '('
        while (i < descriptor.length() && descriptor.charAt(i) != ')') {
            // Skip array brackets
            while (i < descriptor.length() && descriptor.charAt(i) == '[') {
                i++;
            }
            if (i >= descriptor.length()) {
                break;
            }
            char type = descriptor.charAt(i);
            if (type == 'J' || type == 'D') {
                slots += 2;
            } else if (type != 'V') { // void has no slot
                slots += 1;
            }
            i++; // move past the type descriptor
        }
        // After ')', the descriptor might contain a return type which we ignore for popping arguments
    } else {
        // Descriptor is a type descriptor
        while (i < descriptor.length()) {
            while (i < descriptor.length() && descriptor.charAt(i) == '[') {
                i++;
            }
            if (i >= descriptor.length()) {
                break;
            }
            char type = descriptor.charAt(i);
            if (type == 'J' || type == 'D') {
                slots += 2;
            } else if (type != 'V') {
                slots += 1;
            }
            i++;
        }
    }

    if (pos - slots < 0) {
        throw new IllegalStateException(
            "Attempt to pop " + slots + " slots from an empty stack");
    }
    pos -= slots;
}

