        }
        Integer ceil = null;
        for (K k : keys) {
            if (k == null) {
                continue;
            }
            Integer cand;
            try {
                cand = (Integer) k;
            } catch (ClassCastException e) {
                continue;
            }
            if (cand >= val) {
                if (ceil == null || cand < ceil) {
                    ceil = cand;
                }
            }
        }
        bounds.add(ceil);
    }
    return bounds;
}

