static String[] toNoNullStringArray(Object[] array){
    if (array == null) {
        return null;
    }
    int count = 0;
    for (Object obj : array) {
        if (obj != null) {
            count++;
        }
    }
    if (count == array.length) {
        @SuppressWarnings("unchecked")
        String[] result = (String[]) array;
        return result;
    }
    String[] result = new String[count];
    int idx = 0;
    for (Object obj : array) {
        if (obj != null) {
            result[idx++] = (String) obj;
        }
    }
    return result;
}

public static int indexOfExtension(String filename){
    if (filename == null) {
        return -1;
    }
    int dotIndex = filename.lastIndexOf('.');
    if (dotIndex == -1) {
        return -1;
    }
    int lastSlash = filename.lastIndexOf('/');
    int lastBackSlash = filename.lastIndexOf('\\');
    int lastSeparator = Math.max(lastSlash, lastBackSlash);
    if (lastSeparator > dotIndex) {
        return -1;
    }
    return dotIndex;
}

public boolean isExpired(long timestamp, long expiredThreshold) {
    try {
        // An expired threshold of zero or negative indicates immediate expiration
        if (expiredThreshold <= 0) {
            return true;
        }
        // Evaluate if the current time has surpassed the allowed time window
        return System.currentTimeMillis() - timestamp > expiredThreshold;
    } catch (Throwable t) {
        // In case of any unexpected error, assume the metric is expired to avoid keeping stale data
        return true;
    }
}

Edge edgeToNext(){
    Node current = this._currentNode;
    Node next = this._nextNode;
    if (current == null || next == null) {
        return null;
    }
    if (current.isVirtual()) {
        current = current.getRealNode();
    }
    if (next.isVirtual()) {
        next = next.getRealNode();
    }
    for (Edge e : this._edges) {
        if (e.getFrom() == current && e.getTo() == next) {
            return e;
        }
    }
    return null;
}

public static boolean substringMatch(CharSequence str,int index,CharSequence substring){
    if (str == null || substring == null) {
        return false;
    }
    int subLen = substring.length();
    int strLen = str.length();
    if (index < 0 || index + subLen > strLen) {
        return false;
    }
    for (int i = 0; i < subLen; i++) {
        if (str.charAt(index + i) != substring.charAt(i)) {
            return false;
        }
    }
    return true;
}

