private void checkIfPackedField() throws IOException {
    // If there is no field descriptor available, nothing to check
    if (fieldDescriptor == null) {
        return;
    }
    // Determine whether the current field is a repeated packed scalar.
    // In protobuf, packed fields have the "packed" option set on a repeated field.
    boolean shouldBePacked = fieldDescriptor.isRepeated() && fieldDescriptor.isPacked();
    // Update internal state accordingly.  This flag can be used by the reader
    // to know that subsequent values should be interpreted as part of a packed sequence.
    isReadingPacked = shouldBePacked;
}

public int readTag() throws IOException {
    int result = 0;
    int shift = 0;
    while (shift < 32) {
        int b = in.read();
        if (b == -1) {
            return 0; // end of stream reached before any tag read
        }
        result |= (b & 0x7F) << shift;
        if ((b & 0x80) == 0) {
            return result; // complete tag read
        }
        shift += 7;
    }
    throw new IOException("Malformed varint in readTag()");
}

final ByteVector put11(final int byteValue1,final int byteValue2){
    int loc0 = this.length;
    if (loc0 + 2 > this.data.length) {
        enlarge(2);
    }
    byte[] loc1 = this.data;
    loc1[loc0++] = (byte) byteValue1;
    loc1[loc0++] = (byte) byteValue2;
    this.length = loc0;
    return this;
}

private String buildContentRange(){
    try {
        // Assume these fields exist in the surrounding class:
        // long start;   // starting byte index (inclusive)
        // long end;     // ending byte index (inclusive)
        // long totalSize; // total size of the resource
        // If any required field is missing or invalid, return null.
        if (start < 0 || end < 0 || totalSize <= 0) {
            return null;
        }
        if (start > end) {
            return null;
        }
        // Construct the header value in the form: "bytes <start>-<end>/<totalSize>"
        StringBuilder sb = new StringBuilder();
        sb.append("bytes ")
          .append(start)
          .append('-')
          .append(end)
          .append('/')
          .append(totalSize);
        return sb.toString();
    } catch (Exception e) {
        // In case of any unexpected error, return null rather than propagating the exception.
        return null;
    }
}

public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file,List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    List<ThreadSnapshot> snapshots = new ArrayList<>();
    if (file == null || !file.exists() || !file.isFile()) {
        return snapshots; // return empty list for invalid file
    }
    try (BufferedReader reader = new BufferedReader(new FileReader(file))) {
        String line;
        while ((line = reader.readLine()) != null) {
            line = line.trim();
            if (line.isEmpty()) {
                continue;
            }
            // Attempt to create a ThreadSnapshot from the line.
            ThreadSnapshot snapshot;
            try {
                // Assume ThreadSnapshot has a static parse or fromString method.
                // If no such method, fallback to generic constructor handing a string.
                snapshot = ThreadSnapshot.parse(line);
            } catch (NoSuchMethodError | NoSuchFieldError | UnsupportedOperationException e) {
                // If the above static method doesn't exist, try a generic constructor
                try {
                    snapshot = new ThreadSnapshot(line);
                } catch (InstantiationException | IllegalAccessException ex) {
                    // If we cannot instantiate, skip this line
                    continue;
                }
            } catch (Exception e) {
                // Any other parsing exception, skip this line
                continue;
            }
            // Determine if the snapshot's timestamp falls within any time range.
            boolean withinRange = true;
            if (timeRanges != null && !timeRanges.isEmpty()) {
                withinRange = false;
                try {
                    long timestamp = snapshot.getTimestamp();
                    for (ProfileAnalyzeTimeRange range : timeRanges) {
                        if (range == null) {
                            continue;
                        }
                        try {
                            long start = range.getStart();
                            long end = range.getEnd();
                            if (timestamp >= start && timestamp <= end) {
                                withinRange = true;
                                break;
                            }
                        } catch (Exception e) {
                            // If range methods throw, ignore this range
                            continue;
                        }
                    }
                } catch (Exception e) {
                    // If snapshot.getTimestamp() is not available, exclude it
                    withinRange = false;
                }
            }
            if (withinRange) {
                snapshots.add(snapshot);
            }
        }
    }
    return snapshots;
}
